const body = $input.first().json.body;
return [{
  json: {
    proyek: body.proyek,
    proyekId: body.proyekId,
    tanggal: body.tanggal,
    items: body.items || [],
    // GANTI ketiga nilai di bawah ini:
    // ID folder Google Drive "Defect List" (root khusus fitur ini) — dari
    // URL folder: drive.google.com/drive/folders/<ID_INI>
    rootFolderId: "ISI_DENGAN_ID_FOLDER_ROOT_DRIVE_ANDA",
    // URL app Anda, TANPA garis miring di akhir
    appBaseUrl: "https://taracoapp.com",
    // Harus SAMA PERSIS dengan N8N_CALLBACK_SECRET di .env.local app
    callbackSecret: "05f224ab1d0f179c0e4ba76f51c677ac82095e6d1550d73a",
  },
}];

const norm = $('Normalize').first().json;
const found = $input.first().json;
return [{ json: { ...norm, projectFolderId: found.files[0].id } }];

const norm = $('Normalize').first().json;
const created = $input.first().json;
return [{ json: { ...norm, projectFolderId: created.id } }];

const base = $('Folder Proyek Siap').first().json;
const found = $input.first().json;
return [{ json: { ...base, dateFolderId: found.files[0].id } }];

const base = $('Folder Proyek Siap').first().json;
const created = $input.first().json;
return [{ json: { ...base, dateFolderId: created.id } }];

const base = $input.first().json;
const safe = (s) => String(s || '').replace(/[\\/:*?"<>|]/g, '-').slice(0, 60).trim();
const out = [];
for (const it of (base.items || [])) {
  const label = it.jenis === 'bukti' ? 'Bukti - ' : '';
  const media = (it.media && it.media.length) ? it.media : [
    it.fotoUrl ? { mediaId: null, tipe: 'foto', url: it.fotoUrl, ext: it.fotoExt } : null,
    it.videoUrl ? { mediaId: null, tipe: 'video', url: it.videoUrl, ext: it.videoExt } : null,
  ].filter(Boolean);
  media.forEach((m, idx) => {
    const ext = m.ext || (m.tipe === 'video' ? 'mp4' : 'jpg');
    const dup = media.filter((x) => x.tipe === m.tipe).length > 1 ? ` (${idx + 1})` : '';
    out.push({
      json: {
        id: it.id,
        mediaId: m.mediaId,
        no: it.no,
        uraian: it.uraian,
        jenis: it.jenis === 'bukti' ? 'bukti' : 'temuan',
        tipe: m.tipe,
        url: m.url,
        dateFolderId: base.dateFolderId,
        fileName: `${it.no} - ${label}${safe(it.uraian)}${dup}.${ext}`,
      },
      pairedItem: 0,
    });
  });
}
return out;
